"""Seam coverage for the candidate-selection key table (upstream #665/#730/#710).

One decision answers "does this key pick a candidate, and which one" — the
space page-turn and the space confirm coexist, the right-hand NumPad digits
select with NumLock on, and the tables that ship a plain digit row select
without Shift while the others keep the Shift + digit rule.

Cases drive the real 速成 (chesimplex) service with synthesized key events; the
table is replaced by a small synthetic ``Cin`` so the candidate counts are
deterministic.
"""

import io
import json
import os
import sys
import unittest
from unittest.mock import MagicMock

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

import ime_smoke_runner  # noqa: E402
from test_cinbase_shift_to_english import CinbaseKeyHarness  # noqa: E402

from cinbase import CinBase  # noqa: E402

VK_SHIFT = 0x10
VK_NUMLOCK = 0x90
VK_NUMPAD0 = 0x60
VK_NUMPAD1 = 0x61
VK_ADD = 0x6B
VK_NEXT = 0x22


def synthetic_cin(chardefs, keynames, ime="chesimplex"):
    from cinbase.cin import Cin
    payload = json.dumps({
        "chardefs": chardefs,
        "privateuse": {},
        "keynames": keynames,
        "selkey": "".join(str(i % 10) for i in range(10)),
        "ename": "test",
        "cname": "test",
    }, ensure_ascii=False)
    return Cin(io.StringIO(payload), ime, True)


class CinbaseSelectionKeyTests(CinbaseKeyHarness):

    def num_event(self, char_code, key_code, numlock=True, shift=False):
        event = MagicMock()
        event.charCode = char_code
        event.keyCode = key_code
        event.seqNum = 1
        event.repeatCount = 1
        event.scanCode = 0
        event.isExtended = False
        event.keyStates = [0] * 256
        event.isPrintableChar.return_value = True
        event.isKeyDown.side_effect = lambda vk: vk == VK_SHIFT and shift
        event.isKeyToggled.return_value = numlock
        return event

    def send_event(self, service, event):
        service.currentReply = {}
        if service.filterKeyDown(event):
            service.onKeyDown(event)
        return service.currentReply.get("commitString", "")

    def three_candidate_table(self, service):
        service.cin = synthetic_cin(
            {"l": ["甲", "乙", "丙"], "b": ["月"]}, {"l": "︙", "b": "月"})
        service.candPerPage = 2
        service.candPerRow = 2
        service.candidateView.configure(2, 2)

    # --- space page-turn and space confirm coexist (issue #665) ---------------

    def test_space_pages_then_confirms_the_tail_page(self):
        service = self.activate_chesimplex()
        service.directShowCand = False
        service.switchPageWithSpace = True
        self.three_candidate_table(service)

        self.send(service, ord("l"), ord("l"), printable=True)
        self.assertFalse(service.isShowCandidates, "setup: window opens with space")

        self.send(service, 0x20, 0x20, printable=True)  # open
        self.assertEqual(list(service.candidateList), ["甲", "乙"])
        self.assertEqual(service.candidateView.page, 0)

        self.send(service, 0x20, 0x20, printable=True)  # page
        self.assertEqual(service.candidateView.page, 1)
        self.assertEqual(list(service.candidateList), ["丙"])

        # 選字鍵選的是「這一頁」的項目
        self.assertEqual(self.send(service, ord("1"), 0x31, printable=True), "丙")
        self.assertFalse(service.isComposing())

        # 同一個作業階段裡，只有一個候選字的按鍵仍然由空白鍵直接確認
        self.send(service, ord("b"), ord("b"), printable=True)
        self.assertEqual(self.send(service, 0x20, 0x20, printable=True), "月")

    def test_space_confirms_a_single_candidate_while_paging_is_on(self):
        service = self.activate_chesimplex()
        service.directShowCand = False
        service.switchPageWithSpace = True
        service.cin = synthetic_cin({"l": ["甲"]}, {"l": "︙"})

        self.send(service, ord("l"), ord("l"), printable=True)
        self.assertEqual(self.send(service, 0x20, 0x20, printable=True), "甲")

    def test_wildcard_mode_keeps_both_space_roles(self):
        service = self.activate_chesimplex()
        service.directShowCand = False
        service.switchPageWithSpace = True
        service.supportWildcard = True
        service.selWildcardChar = "*"
        service.cin = synthetic_cin(
            {"la": ["甲", "乙", "丙"], "lb": ["丁"]},
            {"l": "︙", "a": "﹚", "b": "﹅"})
        service.candPerPage = 2
        service.candidateView.configure(2, 2)

        self.send(service, ord("*"), 0x38, printable=True, shift=True)
        self.send(service, ord("a"), ord("a"), printable=True)
        self.assertEqual(service.compositionChar, "*a")

        self.send(service, 0x20, 0x20, printable=True)  # open
        self.assertEqual(service.candidateView.page, 0)
        self.assertEqual(list(service.candidateList), ["甲", "乙"])

        self.send(service, 0x20, 0x20, printable=True)  # space pages
        self.assertEqual(service.candidateView.page, 1)
        self.assertEqual(list(service.candidateList), ["丙"])

        self.assertEqual(self.send(service, ord("1"), 0x31, printable=True), "丙")

        # 萬用字元只解出一個字時，同一個空白鍵直接確認
        self.send(service, ord("*"), 0x38, printable=True, shift=True)
        self.send(service, ord("b"), ord("b"), printable=True)
        self.assertEqual(service.compositionChar, "*b")
        self.assertEqual(self.send(service, 0x20, 0x20, printable=True), "丁")

    # --- NumPad digits select with NumLock on (issue #730) --------------------

    def test_numpad_digits_select_the_candidate(self):
        service = self.activate_chesimplex()
        service.directShowCand = False
        service.switchPageWithSpace = False
        self.three_candidate_table(service)

        self.send(service, ord("l"), ord("l"), printable=True)
        self.send(service, 0x20, 0x20, printable=True)  # open the window

        self.assertEqual(
            self.send_event(service, self.num_event(ord("1"), VK_NUMPAD1)), "甲")
        self.assertFalse(service.isComposing())

        self.send(service, ord("l"), ord("l"), printable=True)
        self.send(service, 0x20, 0x20, printable=True)
        self.assertEqual(
            self.send_event(service, self.num_event(ord("2"), VK_NUMPAD1 + 1)), "乙")

    def test_other_numpad_keys_still_bypass_the_ime(self):
        service = self.activate_chesimplex()
        service.directShowCand = False
        service.switchPageWithSpace = False
        self.three_candidate_table(service)

        self.send(service, ord("l"), ord("l"), printable=True)
        self.send(service, 0x20, 0x20, printable=True)
        pageBefore = service.candidateView.page

        self.send_event(service, self.num_event(0, VK_ADD))

        self.assertEqual(service.candidateView.page, pageBefore)
        self.assertEqual(service.currentReply.get("commitString", ""), "")

    def test_numpad_digit_with_the_window_closed_is_claimed_without_committing(self):
        # issue #730 的措辭：數字鍵在「候選清單開著時」是選字鍵；關著時仍由輸入法接管，
        # 不會漏給應用程式，也不會誤送字。
        service = self.activate_chesimplex()
        service.directShowCand = False
        service.switchPageWithSpace = False
        self.three_candidate_table(service)

        self.send(service, ord("l"), ord("l"), printable=True)
        self.assertFalse(service.isShowCandidates, "setup: the window is closed")

        self.assertEqual(
            self.send_event(service, self.num_event(ord("1"), VK_NUMPAD1)), "")
        self.assertTrue(service.isComposing())
        self.assertEqual(service.compositionChar, "l")

    # --- plain digit rows select without Shift (issue #710) -------------------

    def decision(self, ime, row, key, char, shift=False, phrase=False, numlock=False,
                 keyCode=None):
        cbTS = type("S", (), {"imeDirName": ime, "selKeys": row})()
        event = MagicMock()
        event.charCode = ord(char) if char else 0
        event.keyCode = keyCode if keyCode is not None else (ord(char) if char else 0)
        event.isKeyDown.side_effect = lambda vk: vk == VK_SHIFT and shift
        event.isKeyToggled.return_value = numlock
        return CinBase.matchSelKey(cbTS, event, event.charCode, char, phrase)

    def test_decision_table_main_window_rows(self):
        self.assertEqual(self.decision("chesimplex", "1234567890", "1", "1"), 0)
        self.assertEqual(self.decision("chesimplex", "1234567890", "3", "3"), 2)
        self.assertEqual(self.decision("chesimplex", "0123456789", "0", "0"), 0)
        self.assertEqual(self.decision("chesimplex", "0123456789", "2", "2"), 2)
        self.assertIsNone(self.decision("chesimplex", "1234567890", "1", "1", shift=True))
        self.assertIsNone(self.decision("chesimplex", "1234567890", "x", "x"))

    def test_decision_table_phrase_window_shift_rule(self):
        # 一般的碼表：聯想字視窗要 Shift + 數字
        self.assertEqual(
            self.decision("chesimplex", "1234567890", "1", "1", shift=True, phrase=True), 0)
        self.assertIsNone(
            self.decision("chesimplex", "1234567890", "1", "1", phrase=True))
        # 使用數字列的碼表 (大易/行列30)：不需 Shift
        self.assertEqual(
            self.decision("cheliu", "0123456789", "0", "0", phrase=True), 0)
        # 大易的字根列 ('[]-\)：位移比索引大 1，兩個視窗都一樣
        self.assertEqual(
            self.decision("chedayi", "'[]-\\", "[", "[", phrase=True), 2)
        self.assertEqual(
            self.decision("chedayi", "'[]-\\", "[", "["), 2)
        self.assertEqual(
            self.decision("chedayi", "1234567890", "1", "1"), 1)

    def test_decision_table_numpad_row(self):
        self.assertEqual(
            self.decision("chesimplex", "1234567890", "1", "1",
                          numlock=True, keyCode=VK_NUMPAD1), 0)
        # NumLock 沒亮時小鍵盤鍵不是選字鍵
        self.assertIsNone(
            self.decision("chesimplex", "1234567890", "", "",
                          numlock=False, keyCode=VK_NUMPAD1))

    def test_configured_row_drives_the_main_window(self):
        service = self.activate_chesimplex()
        service.directShowCand = False
        service.switchPageWithSpace = False
        service.cin = synthetic_cin({"l": ["甲", "乙", "丙"]}, {"l": "︙"})
        service.candPerPage = 9
        service.candidateView.configure(9, 3)
        service.cfg.selKeyType = 1  # 0123456789
        service.selKeys = service.cfg.getSelKeys()

        self.send(service, ord("l"), ord("l"), printable=True)
        self.send(service, 0x20, 0x20, printable=True)

        self.assertEqual(self.send(service, ord("0"), 0x30, printable=True), "甲")


